import{_ as e}from"./chunks/storefront.DajPQLZU.js";import{_ as a,o as r,c as s,a7 as d}from"./chunks/framework.C4ZIv4ii.js";const b=JSON.parse('{"title":"Storefront","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/storefront.md","filePath":"ecommerce/storefront.md","lastUpdated":1788111091000}'),o={name:"ecommerce/storefront.md"};function i(n,t,l,h,c,p){return r(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="storefront" tabindex="-1">Storefront <a class="header-anchor" href="#storefront" aria-label="Permalink to &quot;Storefront&quot;">​</a></h1><p>What shoppers see outside the admin: the shop archive and its filters, the customer account, and the structured data search engines read.</p><p><img src="'+e+`" alt="The shop archive"></p><p><em>The shop archive as the default theme renders it — filter sidebar, product grid, sale badges, and add-to-cart.</em></p><h2 id="shop-filters" tabindex="-1">Shop filters <a class="header-anchor" href="#shop-filters" aria-label="Permalink to &quot;Shop filters&quot;">​</a></h2><p>The shop page and every product category archive carry a filter sidebar:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Source</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>Product title, excerpt and SKU — including variation SKUs</td></tr><tr><td><strong>Price</strong></td><td>A dual-handle slider bounded by the cheapest and dearest product on offer</td></tr><tr><td><strong>Category</strong></td><td>Product categories, with a count each</td></tr><tr><td><strong>Attributes</strong></td><td>Every attribute marked <em>Show in filters</em> — see <a href="/falconcms/ecommerce/products.html#attributes">Products</a></td></tr><tr><td><strong>In stock only</strong></td><td>The same availability rule the stock badge uses</td></tr><tr><td><strong>On sale</strong></td><td>Only sales that are actually running</td></tr></tbody></table><p>Filtering happens over AJAX and rewrites the address bar, so:</p><ul><li>a filtered view is a real URL you can share or bookmark</li><li>the back button steps back through the filters</li><li>sorting and pagination keep the filters applied</li></ul><p>With JavaScript switched off the panel is a plain GET form with an <strong>Apply filters</strong> button, and every filter still works.</p><h3 id="urls" tabindex="-1">URLs <a class="header-anchor" href="#urls" aria-label="Permalink to &quot;URLs&quot;">​</a></h3><p>Filters are ordinary query parameters, so you can link straight to a filtered view:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/product?s=phone&amp;min_price=1000&amp;max_price=25000</span></span>
<span class="line"><span>/product?product_cat[]=samsung&amp;in_stock=1</span></span>
<span class="line"><span>/product?attr[color][]=blue&amp;attr[size][]=xl&amp;on_sale=1</span></span></code></pre></div><p>Values within one attribute are OR&#39;d, separate attributes are AND&#39;d — picking Red and Blue widens the results, adding a size narrows them.</p><h3 id="the-attribute-index" tabindex="-1">The attribute index <a class="header-anchor" href="#the-attribute-index" aria-label="Permalink to &quot;The attribute index&quot;">​</a></h3><p>Attribute filtering reads a derived table that is rebuilt whenever a product is saved. If it ever drifts — after a bulk import, or a direct database edit — rebuild it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> falcon:reindex-attributes</span></span></code></pre></div><h2 id="related-upsells-and-cross-sells" tabindex="-1">Related, upsells and cross-sells <a class="header-anchor" href="#related-upsells-and-cross-sells" aria-label="Permalink to &quot;Related, upsells and cross-sells&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Row</th><th>Where</th><th>Chosen by</th></tr></thead><tbody><tr><td><strong>You may also like</strong></td><td>Product page</td><td>You, in <em>Product Data → Linked Products</em></td></tr><tr><td><strong>Related products</strong></td><td>Product page</td><td>Automatically, from the product&#39;s category</td></tr><tr><td><strong>You may be interested in</strong></td><td>Cart</td><td>You, as cross-sells on the products in the cart</td></tr></tbody></table><p>Cross-sells never suggest something already in the cart.</p><h2 id="customer-accounts" tabindex="-1">Customer accounts <a class="header-anchor" href="#customer-accounts" aria-label="Permalink to &quot;Customer accounts&quot;">​</a></h2><p>Under <strong>My Account</strong>, signed-in customers get orders, downloads, profile, password — and:</p><h3 id="saved-addresses" tabindex="-1">Saved addresses <a class="header-anchor" href="#saved-addresses" aria-label="Permalink to &quot;Saved addresses&quot;">​</a></h3><p>Customers save addresses under <strong>My Account → Addresses</strong>, each with an optional label (<em>Home</em>, <em>Office</em>). Separate defaults are kept for billing and shipping, because being billed at home and shipped to work is ordinary.</p><p>At checkout the default address fills the form server-side, so it works with JavaScript off. When more than one address is saved, a picker appears to switch between them. A <strong>Save this address</strong> tick on checkout adds the address after the order is placed — near duplicates are recognised and not added twice.</p><h2 id="structured-data" tabindex="-1">Structured data <a class="header-anchor" href="#structured-data" aria-label="Permalink to &quot;Structured data&quot;">​</a></h2><p>Product pages emit schema.org JSON-LD, which is what puts price, availability and star ratings into a search result instead of a bare link.</p><table tabindex="0"><thead><tr><th>Product</th><th>Markup</th></tr></thead><tbody><tr><td>Simple</td><td><code>Offer</code> with price, currency, availability, and <code>priceValidUntil</code> while a sale runs</td></tr><tr><td>Variable</td><td><code>AggregateOffer</code> with <code>lowPrice</code>, <code>highPrice</code> and <code>offerCount</code></td></tr></tbody></table><p>Reviews add an <code>aggregateRating</code>. An attribute named <em>Brand</em> is emitted as the product&#39;s brand.</p><p>Prices in the markup come from the same helper the page itself uses, so the structured data can never advertise a price the shop will not honour — search engines treat that as a violation, not a rounding error.</p><h3 id="testing-it" tabindex="-1">Testing it <a class="header-anchor" href="#testing-it" aria-label="Permalink to &quot;Testing it&quot;">​</a></h3><p>Paste the page&#39;s JSON-LD into <a href="https://search.google.com/test/rich-results" target="_blank" rel="noreferrer">Google&#39;s Rich Results Test</a> using the <strong>Code</strong> tab. Once the site is public, test by <strong>URL</strong> instead — a rich result only appears when the product URL and its image are reachable from the internet.</p>`,32)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
